-- =============================================================================
-- ABSENSI RFID & PRESENSI DIGITAL SMK NU WARGABINANGUN
-- Database Schema (DDL - Struktur Tabel Bersih Tanpa Data Pribadi)
-- Catatan Privasi: Berkas ini hanya memuat definisi CREATE TABLE (DDL).
-- Seluruh rekaman data pribadi siswa dan guru dikecualikan sesuai standar privasi.
-- =============================================================================

CREATE DATABASE IF NOT EXISTS `absensi_rfid` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `absensi_rfid`;

SET FOREIGN_KEY_CHECKS = 0;

-- Table structure for table `absensi_guru`

DROP TABLE IF EXISTS `absensi_guru`;
CREATE TABLE `absensi_guru` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `guru_id` int(11) NOT NULL,
  `tanggal` date NOT NULL,
  `jam_datang` time DEFAULT NULL,
  `jam_pulang` time DEFAULT NULL,
  `status` enum('hadir','terlambat','izin','sakit','alfa','gagal') DEFAULT 'alfa',
  `keterangan` text DEFAULT NULL,
  `source_device_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `guru_id` (`guru_id`,`tanggal`),
  KEY `source_device_id` (`source_device_id`),
  KEY `idx_absensi_guru_tgl_status` (`tanggal`,`status`),
  CONSTRAINT `absensi_guru_ibfk_1` FOREIGN KEY (`guru_id`) REFERENCES `guru` (`id`) ON DELETE CASCADE,
  CONSTRAINT `absensi_guru_ibfk_2` FOREIGN KEY (`source_device_id`) REFERENCES `iot_devices` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `absensi_siswa`

DROP TABLE IF EXISTS `absensi_siswa`;
CREATE TABLE `absensi_siswa` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `siswa_id` int(11) NOT NULL,
  `tanggal` date NOT NULL,
  `jam_datang` time DEFAULT NULL,
  `jam_pulang` time DEFAULT NULL,
  `status` enum('hadir','terlambat','izin','sakit','alfa','pulang_cepat','pkl') DEFAULT 'alfa',
  `keterangan` text DEFAULT NULL,
  `foto_masuk` varchar(255) DEFAULT NULL,
  `foto_pulang` varchar(255) DEFAULT NULL,
  `latitude_masuk` decimal(11,8) DEFAULT NULL,
  `longitude_masuk` decimal(11,8) DEFAULT NULL,
  `latitude_pulang` decimal(11,8) DEFAULT NULL,
  `longitude_pulang` decimal(11,8) DEFAULT NULL,
  `jarak_meter` int(11) DEFAULT NULL,
  `source_device_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `siswa_id` (`siswa_id`,`tanggal`),
  KEY `source_device_id` (`source_device_id`),
  KEY `idx_absensi_siswa_tgl_status` (`tanggal`,`status`),
  CONSTRAINT `absensi_siswa_ibfk_1` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE,
  CONSTRAINT `absensi_siswa_ibfk_2` FOREIGN KEY (`source_device_id`) REFERENCES `iot_devices` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `app_settings`

DROP TABLE IF EXISTS `app_settings`;
CREATE TABLE `app_settings` (
  `setting_key` varchar(50) NOT NULL,
  `setting_value` text DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `catatan_guru`

DROP TABLE IF EXISTS `catatan_guru`;
CREATE TABLE `catatan_guru` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `guru_id` int(11) NOT NULL,
  `kepsek_id` int(11) NOT NULL,
  `catatan` text NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `guru_id` (`guru_id`),
  KEY `kepsek_id` (`kepsek_id`),
  CONSTRAINT `catatan_guru_ibfk_1` FOREIGN KEY (`guru_id`) REFERENCES `guru` (`id`) ON DELETE CASCADE,
  CONSTRAINT `catatan_guru_ibfk_2` FOREIGN KEY (`kepsek_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `catatan_siswa`

DROP TABLE IF EXISTS `catatan_siswa`;
CREATE TABLE `catatan_siswa` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `siswa_id` int(11) NOT NULL,
  `wali_kelas_id` int(11) NOT NULL,
  `catatan` text NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `siswa_id` (`siswa_id`),
  KEY `wali_kelas_id` (`wali_kelas_id`),
  CONSTRAINT `catatan_siswa_ibfk_1` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE,
  CONSTRAINT `catatan_siswa_ibfk_2` FOREIGN KEY (`wali_kelas_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `chat_history`

DROP TABLE IF EXISTS `chat_history`;
CREATE TABLE `chat_history` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `pesan_user` text NOT NULL,
  `balasan_bot` text NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `chat_history_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `guru`

DROP TABLE IF EXISTS `guru`;
CREATE TABLE `guru` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `nip` varchar(20) NOT NULL,
  `barcode_id` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `subject` varchar(255) DEFAULT NULL,
  `is_pembimbing_pkl` tinyint(1) NOT NULL DEFAULT 0,
  `telegram_chat_id` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nip` (`nip`),
  UNIQUE KEY `barcode_id` (`barcode_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `guru_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `iot_devices`

DROP TABLE IF EXISTS `iot_devices`;
CREATE TABLE `iot_devices` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `device_code` varchar(50) NOT NULL,
  `device_name` varchar(100) NOT NULL,
  `device_type` enum('RFID_SISWA') NOT NULL,
  `location` varchar(100) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `api_key_hash` varchar(255) NOT NULL,
  `status` enum('active','inactive') DEFAULT 'active',
  `app_mode` enum('absen','regis') DEFAULT 'absen',
  `last_scanned_uid` varchar(50) DEFAULT NULL,
  `last_scan_time` timestamp NULL DEFAULT NULL,
  `last_seen` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `pending_ssid` varchar(64) DEFAULT NULL,
  `pending_pass` varchar(64) DEFAULT NULL,
  `pending_host` varchar(100) DEFAULT NULL,
  `wifi_ssid` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `device_code` (`device_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `iot_logs`

DROP TABLE IF EXISTS `iot_logs`;
CREATE TABLE `iot_logs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `device_id` int(11) NOT NULL,
  `payload` text NOT NULL,
  `response_code` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `device_id` (`device_id`),
  CONSTRAINT `iot_logs_ibfk_1` FOREIGN KEY (`device_id`) REFERENCES `iot_devices` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `jadwal_absensi`

DROP TABLE IF EXISTS `jadwal_absensi`;
CREATE TABLE `jadwal_absensi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `hari` enum('Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu') NOT NULL,
  `jam_mulai_absensi` time NOT NULL,
  `jam_datang` time NOT NULL,
  `batas_terlambat` time NOT NULL,
  `jam_pulang` time NOT NULL,
  `status_aktif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `hari` (`hari`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `jadwal_guru`

DROP TABLE IF EXISTS `jadwal_guru`;
CREATE TABLE `jadwal_guru` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `guru_id` int(11) NOT NULL,
  `hari` enum('Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu') NOT NULL,
  `jam_mulai_absensi` time NOT NULL,
  `jam_datang` time NOT NULL,
  `batas_terlambat` time NOT NULL,
  `jam_pulang` time NOT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `guru_id` (`guru_id`,`hari`),
  CONSTRAINT `jadwal_guru_ibfk_1` FOREIGN KEY (`guru_id`) REFERENCES `guru` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `jadwal_siswa`

DROP TABLE IF EXISTS `jadwal_siswa`;
CREATE TABLE `jadwal_siswa` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `hari` enum('Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu') NOT NULL,
  `jam_mulai_absensi` time NOT NULL,
  `jam_datang` time NOT NULL,
  `batas_terlambat` time NOT NULL,
  `jam_pulang` time NOT NULL,
  `status_aktif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `jam_pulang_awal` time DEFAULT NULL COMMENT 'Batas awal siswa boleh scan pulang',
  PRIMARY KEY (`id`),
  UNIQUE KEY `hari` (`hari`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `kelas`

DROP TABLE IF EXISTS `kelas`;
CREATE TABLE `kelas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `class_code` varchar(20) NOT NULL,
  `nama_kelas` varchar(50) NOT NULL,
  `wali_kelas_id` int(11) DEFAULT NULL,
  `telegram_chat_id` varchar(50) DEFAULT NULL,
  `telegram_chat_id_pkl` varchar(50) DEFAULT NULL,
  `wa_config_id` int(11) DEFAULT NULL,
  `no_wa_wali_kelas` varchar(20) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `status` enum('aktif','pkl') DEFAULT 'aktif',
  `telegram_bot_token` varchar(100) DEFAULT NULL COMMENT 'Token Bot Telegram per kelas dari BotFather',
  `jurusan` varchar(50) DEFAULT NULL,
  `tingkat` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `class_code` (`class_code`),
  KEY `wali_kelas_id` (`wali_kelas_id`),
  CONSTRAINT `kelas_ibfk_1` FOREIGN KEY (`wali_kelas_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `log_error_absensi`

DROP TABLE IF EXISTS `log_error_absensi`;
CREATE TABLE `log_error_absensi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `request_id` varchar(50) NOT NULL,
  `waktu` timestamp NOT NULL DEFAULT current_timestamp(),
  `sumber` enum('scan_kamera','scan_manual','backend','client') NOT NULL,
  `barcode_input` varchar(255) DEFAULT NULL,
  `jenis_error` varchar(100) NOT NULL,
  `pesan_error` text NOT NULL,
  `user_agent` text DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `notifikasi`

DROP TABLE IF EXISTS `notifikasi`;
CREATE TABLE `notifikasi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `judul` varchar(150) NOT NULL,
  `pesan` text NOT NULL,
  `tipe` varchar(50) NOT NULL DEFAULT 'general',
  `url` varchar(255) DEFAULT NULL,
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_user_read_time` (`user_id`,`is_read`,`created_at`),
  CONSTRAINT `notifikasi_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for table `pengajuan_izin`

DROP TABLE IF EXISTS `pengajuan_izin`;
CREATE TABLE `pengajuan_izin` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `tanggal_mulai` date NOT NULL,
  `tanggal_selesai` date NOT NULL,
  `jenis` enum('sakit','izin') NOT NULL,
  `alasan` text NOT NULL,
  `keterangan` text DEFAULT NULL,
  `file_bukti` varchar(255) DEFAULT NULL,
  `status` enum('pending','approved','rejected') DEFAULT 'pending',
  `approved_by` int(11) DEFAULT NULL,
  `catatan_approval` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `approved_by` (`approved_by`),
  KEY `idx_izin_status_tgl` (`status`,`tanggal_mulai`,`tanggal_selesai`),
  CONSTRAINT `pengajuan_izin_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pengajuan_izin_ibfk_2` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `pengajuan_pulang_cepat`

DROP TABLE IF EXISTS `pengajuan_pulang_cepat`;
CREATE TABLE `pengajuan_pulang_cepat` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `siswa_id` int(11) NOT NULL,
  `wali_kelas_id` int(11) NOT NULL,
  `tanggal` date NOT NULL,
  `jam_pengajuan` time NOT NULL,
  `jam_masuk` time DEFAULT NULL,
  `jam_pulang_jadwal` time DEFAULT NULL,
  `alasan` text DEFAULT NULL,
  `status` enum('DRAFT','PENDING','APPROVED','REJECTED') DEFAULT 'DRAFT',
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `rejected_by` int(11) DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `rejected_reason` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `wali_kelas_id` (`wali_kelas_id`),
  KEY `approved_by` (`approved_by`),
  KEY `rejected_by` (`rejected_by`),
  KEY `idx_siswa_tanggal_status` (`siswa_id`,`tanggal`,`status`),
  CONSTRAINT `pengajuan_pulang_cepat_ibfk_1` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pengajuan_pulang_cepat_ibfk_2` FOREIGN KEY (`wali_kelas_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pengajuan_pulang_cepat_ibfk_3` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pengajuan_pulang_cepat_ibfk_4` FOREIGN KEY (`rejected_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `permohonan_pulang_cepat`

DROP TABLE IF EXISTS `permohonan_pulang_cepat`;
CREATE TABLE `permohonan_pulang_cepat` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `siswa_id` int(11) NOT NULL,
  `absensi_id` int(11) NOT NULL,
  `tanggal` date NOT NULL,
  `jam_request` time NOT NULL,
  `alasan_kategori` enum('izin','sakit','lainnya') NOT NULL DEFAULT 'lainnya',
  `alasan_detail` varchar(500) DEFAULT NULL,
  `status` enum('pending','disetujui','ditolak') NOT NULL DEFAULT 'pending',
  `diproses_oleh` int(11) DEFAULT NULL COMMENT 'user_id admin/wali yang memproses',
  `diproses_pada` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_tanggal` (`tanggal`),
  KEY `idx_status` (`status`),
  KEY `idx_siswa` (`siswa_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for table `pkl_kelompok`

DROP TABLE IF EXISTS `pkl_kelompok`;
CREATE TABLE `pkl_kelompok` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kelas_id` int(11) NOT NULL,
  `nama_kelompok` varchar(100) NOT NULL,
  `nama_tempat` varchar(150) NOT NULL,
  `alamat` text DEFAULT NULL,
  `link_lokasi` text DEFAULT NULL,
  `latitude` decimal(11,8) NOT NULL,
  `longitude` decimal(11,8) NOT NULL,
  `radius_meter` int(11) DEFAULT 50,
  `pembimbing_guru_id` int(11) DEFAULT NULL,
  `pembimbing_nama` varchar(100) DEFAULT NULL,
  `pembimbing_kontak` varchar(50) DEFAULT NULL,
  `hari_kerja` varchar(100) NOT NULL DEFAULT '["Senin","Selasa","Rabu","Kamis","Jumat"]',
  `is_jam_bebas` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `kelas_id` (`kelas_id`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `pkl_kelompok_ibfk_1` FOREIGN KEY (`kelas_id`) REFERENCES `kelas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pkl_kelompok_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `pkl_kelompok_siswa`

DROP TABLE IF EXISTS `pkl_kelompok_siswa`;
CREATE TABLE `pkl_kelompok_siswa` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kelompok_id` int(11) NOT NULL,
  `siswa_id` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `siswa_id` (`siswa_id`),
  KEY `kelompok_id` (`kelompok_id`),
  CONSTRAINT `pkl_kelompok_siswa_ibfk_1` FOREIGN KEY (`kelompok_id`) REFERENCES `pkl_kelompok` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pkl_kelompok_siswa_ibfk_2` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `pkl_pembimbing_kelas`

DROP TABLE IF EXISTS `pkl_pembimbing_kelas`;
CREATE TABLE `pkl_pembimbing_kelas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `guru_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `kelas_id` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pembimbing_kelas` (`guru_id`,`kelas_id`),
  KEY `kelas_id` (`kelas_id`),
  CONSTRAINT `pkl_pembimbing_kelas_ibfk_1` FOREIGN KEY (`guru_id`) REFERENCES `guru` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pkl_pembimbing_kelas_ibfk_2` FOREIGN KEY (`kelas_id`) REFERENCES `kelas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `push_subscriptions`

DROP TABLE IF EXISTS `push_subscriptions`;
CREATE TABLE `push_subscriptions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `endpoint` text NOT NULL,
  `p256dh_key` text DEFAULT NULL,
  `auth_key` text DEFAULT NULL,
  `fcm_token` text DEFAULT NULL,
  `device_info` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_user_push` (`user_id`),
