-- Table structure for table `rfid_cards`

DROP TABLE IF EXISTS `rfid_cards`;
CREATE TABLE `rfid_cards` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `uid` varchar(50) NOT NULL,
  `student_id` int(11) NOT NULL,
  `status` enum('active','inactive') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uid` (`uid`),
  KEY `student_id` (`student_id`),
  CONSTRAINT `rfid_cards_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `siswa`

DROP TABLE IF EXISTS `siswa`;
CREATE TABLE `siswa` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `kelas_id` int(11) DEFAULT NULL,
  `nis` varchar(20) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `rfid_uid` varchar(255) DEFAULT NULL,
  `no_hp_ortu` varchar(20) DEFAULT NULL,
  `wa_notif_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nis` (`nis`),
  KEY `user_id` (`user_id`),
  KEY `idx_siswa_kelas_id` (`kelas_id`),
  CONSTRAINT `siswa_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `siswa_ibfk_2` FOREIGN KEY (`kelas_id`) REFERENCES `kelas` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `siswa_pkl_lokasi`

DROP TABLE IF EXISTS `siswa_pkl_lokasi`;
CREATE TABLE `siswa_pkl_lokasi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `siswa_id` int(11) NOT NULL,
  `nama_tempat` varchar(150) NOT NULL,
  `alamat` text DEFAULT NULL,
  `link_lokasi` text DEFAULT NULL,
  `latitude` decimal(11,8) NOT NULL,
  `longitude` decimal(11,8) NOT NULL,
  `radius_meter` int(11) DEFAULT 10,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `siswa_id` (`siswa_id`),
  CONSTRAINT `siswa_pkl_lokasi_ibfk_1` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `users`

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `name` varchar(100) NOT NULL,
  `role` enum('admin','kepsek','walikelas','wali_kelas','guru','siswa') NOT NULL,
  `telegram_chat_id` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `avatar` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `wa_config`

DROP TABLE IF EXISTS `wa_config`;
CREATE TABLE `wa_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `label` varchar(50) NOT NULL DEFAULT 'Device Utama',
  `kelas_id` int(11) DEFAULT NULL,
  `token` varchar(255) NOT NULL,
  `device_number` varchar(20) NOT NULL,
  `max_per_minute` int(11) NOT NULL DEFAULT 5,
  `delay_seconds` int(11) DEFAULT 12,
  `priority` int(11) NOT NULL DEFAULT 1,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_exhausted` tinyint(1) NOT NULL DEFAULT 0,
  `exhausted_reason` varchar(255) DEFAULT NULL,
  `exhausted_month` varchar(7) DEFAULT NULL,
  `last_used_at` timestamp NULL DEFAULT NULL,
  `total_sent_today` int(11) NOT NULL DEFAULT 0,
  `total_sent_today_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for table `wa_queue`

DROP TABLE IF EXISTS `wa_queue`;
CREATE TABLE `wa_queue` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `config_id` int(11) DEFAULT NULL,
  `siswa_id` int(11) DEFAULT NULL,
  `target_phone` varchar(20) NOT NULL,
  `message` text NOT NULL,
  `notif_type` enum('masuk','pulang','pulang_cepat','alfa','terlambat','info') DEFAULT 'info',
  `status` enum('pending','sending','sent','failed') NOT NULL DEFAULT 'pending',
  `attempt` int(11) NOT NULL DEFAULT 0,
  `max_attempt` int(11) NOT NULL DEFAULT 3,
  `response` text DEFAULT NULL,
  `scheduled_at` timestamp NULL DEFAULT NULL,
  `sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `config_id` (`config_id`),
  KEY `siswa_id` (`siswa_id`),
  KEY `idx_wa_queue_status` (`status`),
  KEY `idx_wa_queue_created` (`created_at`),
  CONSTRAINT `wa_queue_ibfk_1` FOREIGN KEY (`config_id`) REFERENCES `wa_config` (`id`) ON DELETE SET NULL,
  CONSTRAINT `wa_queue_ibfk_2` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

SET FOREIGN_KEY_CHECKS = 1;
